// Reuses the real main/preload workspace fixture, never the user's data directory.
const assert = require('node:assert/strict');
module.exports = async ({ run, click, disk, shot, window }) => {
  await click('[data-view="calendar"]');
  assert.equal(await run('document.querySelector("[data-cal-view=month]").getAttribute("aria-pressed")'),'true');
  assert.equal(await run('document.querySelectorAll(".desktop-calendar-week").length'),6);
  assert.equal(await run('document.querySelector(".nav [data-view=chat-monitor]")'),null);
  assert.equal(await run('document.querySelector("#desktop-module-chat-monitor")'),null);
  await click('#desktop-demo-calendar');
  const count=disk().data.plans.length+disk().data.tasks.length;
  await click('#desktop-demo-calendar');assert.equal(disk().data.plans.length+disk().data.tasks.length,count);
  await run(`(()=>{const input=document.querySelector('#desktop-calendar-jump');input.value='2026-10-21';input.dispatchEvent(new Event('change',{bubbles:true}));return true;})()`);
  assert.equal(await run('document.querySelectorAll(".desktop-calendar-month .cal-deadline").length>0'),true);
  assert.equal(await run('document.querySelectorAll(".desktop-calendar-month .cal-phase").length>0'),true);
  assert.equal(await run('document.querySelector("#desktop-calendar-floating").textContent.includes("长期阅读")'),true);
  window.setSize(1440,1000);await run('document.querySelector(".main").scrollTop=0;true');await click('#desktop-dismiss-notice');await shot('calendar-month-wide.png');
  const pick=async(title,type='schedule')=>run(`(()=>{const b=[...document.querySelectorAll('#desktop-calendar-grid [data-cal-entry]')].find(b=>b.classList.contains('cal-${type}')&&b.textContent.includes(${JSON.stringify(title)}));if(!b)throw Error('Missing calendar event');b.click();return true;})()`);
  await pick('四周小项目');
  assert.equal(await run('document.querySelector("#desktop-calendar-detail").textContent.includes("2026-11-15")'),true);
  await click('[data-cal-edit]');
  assert.equal(await run('document.querySelector(".main").dataset.activeView'),'plans');
  assert.equal(await run('document.querySelector("#desktop-plan-form").hidden'),false);
  assert.equal(await run('document.querySelector("#desktop-plan-form [name=title]").value'),'四周小项目（已编辑）');
  await click('#desktop-cancel-plan');await click('[data-view="calendar"]');
  await click('[data-cal-view="week"]');
  assert.equal(disk().data.preferences.calendar.view,'week');
  assert.equal(await run('document.querySelectorAll(".desktop-calendar-time-day").length'),7);
  await pick('周三项目讨论');
  assert.equal(await run('document.querySelector("#desktop-calendar-detail").textContent.includes("15:00")'),true);
  await shot('calendar-week-wide.png');
  // Only this occurrence is completed; later weeks remain visible.
  await pick('每周阅读');await click('[data-cal-complete]');
  const weekly=disk().data.plans.find(p=>p.id==='demo-plan-5');assert.equal(weekly.completedDates.length,1);
  await click('[data-cal-filter="completed"]');
  await pick('每周阅读');assert.equal(await run('document.querySelector("[data-cal-complete]").textContent.includes("恢复")'),true);
  await click('[data-cal-complete]');assert.equal(disk().data.plans.find(p=>p.id===weekly.id).completedDates.length,0);
  await click('[data-cal-filter="completed"]');
  await click('[data-cal-view="day"]');
  assert.equal(await run('document.querySelectorAll(".desktop-calendar-time-day").length'),1);
  await click('[data-cal-step="1"]');
  await click('[data-cal-add="task"]');
  const date=await run('document.querySelector("#desktop-task-form [name=date]").value');
  assert.match(date,/^2026-10-/);
  await run('document.querySelector("#desktop-task-form [name=title]").value="日历新增待办";document.querySelector("#desktop-task-form [name=time]").value="18:30";document.querySelector("#desktop-task-form").requestSubmit();true');
  assert.equal(disk().data.tasks.find(t=>t.title==='日历新增待办').anchor.date,date);
  await click('[data-view="calendar"]');await click('[data-cal-view="month"]');
  await pick('日历新增待办','deadline');
  assert.equal(await run('document.querySelector("#desktop-calendar-detail").textContent.includes("18:30")'),true);
  await click('[data-cal-edit]');assert.equal(await run('document.querySelector("#desktop-task-form [name=time]").value'),'18:30');
  await run('document.querySelector("#desktop-task-form").requestSubmit();true');
  await click('[data-view="calendar"]');await pick('日历新增待办','deadline');await click('[data-cal-complete]');
  assert.equal(disk().data.tasks.find(t=>t.title==='日历新增待办').done,true);
  await pick('整理本周复习计划');
  await click('#desktop-calendar-detail [data-cal-phase]:not(:checked)');
  assert.equal(disk().data.plans.find(p=>p.id==='demo-plan-range-v1').phases[0].done,true);
  await click('#desktop-calendar-detail [data-cal-phase]:checked');
  await click('[data-cal-filter="plans"]');
  assert.equal(await run('document.querySelectorAll("#desktop-calendar-grid .cal-plan").length'),0);
  await click('[data-cal-filter="plans"]');
  await run(`(()=>{const d=document.querySelector('#desktop-calendar-jump');d.value='2026-10-21';d.dispatchEvent(new Event('change',{bubbles:true}));const b=document.querySelector('[data-cal-date="2026-10-21"]');b.focus();b.dispatchEvent(new KeyboardEvent('keydown',{key:'ArrowRight',bubbles:true}));return true;})()`);
  assert.equal(await run('document.activeElement.dataset.calDate'),'2026-10-22');
  assert.equal(await run('document.querySelector("#desktop-calendar-jump").value'),'2026-10-22');
  await run(`for(const view of ['day','month','week','month'])document.querySelector('[data-cal-view="'+view+'"]').click();true`);
  assert.ok(await run('document.getAnimations().filter(a=>a.id==="desktop-calendar-view").length===1'));
  window.setSize(900,700);await click('#desktop-dismiss-notice');await run('document.querySelector(".main").scrollTop=0;true');await shot('calendar-month-compact.png');
  assert.equal(await run('document.querySelector(".main").scrollWidth<=document.querySelector(".main").clientWidth+1'),true);
  await click('[data-cal-view="week"]');await shot('calendar-week-compact.png');
  assert.equal(await run('document.querySelector(".main").scrollWidth<=document.querySelector(".main").clientWidth+1'),true);
  await click('.nav [data-view="plugins"]');await click('#desktop-module-plans');await click('[data-view="calendar"]');
  assert.equal(await run('document.querySelectorAll("#desktop-calendar-grid .cal-plan").length'),0);
  assert.equal(await run('document.querySelector("[data-cal-filter=plans]").disabled'),true);
  await click('.nav [data-view="plugins"]');await click('#desktop-module-plans');await click('[data-view="calendar"]');
  assert.equal(disk().data.preferences.calendar.view,'week');
  console.log('PASS: calendar month/week/day, deadline and range separation, phase and floating lists, precise times, existing editor links, dated additions, completion and weekly occurrence identity, filters/module isolation, keyboard dates, interruptible motion and portable preferences.');
};
